export class Alumno {
  legajo;
  nombre;
  promedio;
  carrera;
  registros;
  constructor(legajo, nombre, promedio, carrera, registros) {
    this.legajo = legajo;
    this.nombre = nombre;
    this.promedio = promedio;
    this.carrera = carrera;
    this.registros = registros;
  }
  getLegajo() {
    return this.legajo;
  }
  getNombre() {
    return this.nombre;
  }
  getPromedio() {
    return this.promedio;
  }
  getCarrera() {
    return this.carrera;
  }
  getRegistros() {
    return this.registros;
  }
  getMateriasAprobadas() {
    return this.registros.filter(r => r.estaAprobada()).map(r => r.getMateria());
  }
  getMateriasDisponibles() {
    const aprobadas = this.getMateriasAprobadas();
    return this.carrera.getPlanEstudio().getMaterias().filter(m => !aprobadas.find(a => a.getCodigo() === m.getCodigo())).filter(m => m.estaDisponible(aprobadas));
  }
  getPorcentajeAvance() {
    const total = this.carrera.getTotalMaterias();
    if (total === 0) return 0;
    return Math.round(this.getCantidadAprobadas() / total * 100);
  }
  getCantidadAprobadas() {
    return this.getMateriasAprobadas().length;
  }
}
